from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///users.db'
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    message = db.Column(db.String(200), nullable=False)

    def __repr__(self):
        return f'<User {self.username}>'

@app.route('/post', methods=['POST'])
def post():
    data = request.get_json()
    username = data.get('username')
    message = data.get('message')

    if not username or not message:
        return jsonify({'error': 'Username and message are required'}), 400

    user = User(username=username, message=message)
    db.session.add(user)
    db.session.commit()

    return jsonify({'message': 'Message posted successfully'}), 201

@app.route('/get_messages', methods=['GET'])
def get_messages():
    users = User.query.all()
    messages = [{'username': user.username, 'message': user.message} for user in users]
    return jsonify(messages)

@app.route('/clear_messages', methods=['DELETE'])
def clear_messages():
    User.query.delete()
    db.session.commit()
    return jsonify({'message': 'All messages cleared'}), 200

if __name__ == '__main__':
    with app.app_context():
        db.create_all()
    app.run(debug=True)

